answers.solution:
The limiter is sharded (16 shards by default, configurable), each shard owning a mutex, a `map[string]*bucket`, and a `container/list` LRU. Refill is computed lazily inside `refill()` on every access — no background goroutines, no timers. Two properties are load-bearing:

1. **Backwards clock ⇒ no over-grant.** Each operation reads the clock once (`time.Now` by default, which carries the monotonic component, so it can never actually go backward). Negative elapsed time is clamped to zero and the bucket's `last` timestamp is only advanced when real time passes, so a wall-clock jump backwards grants nothing. This mirrors monotonic-clock semantics even under an adversarial injected clock.
2. **Exact accounting.** Tokens are recomputed as `tokens + elapsed·rate` and then hard-capped at `burst` on every access. A full bucket at `t0` stays exactly `burst` at `t0+1s` (never `burst+ε`, never drifting above the cap), and grants are exactly `min(burst, tokens + elapsed·rate)`.

`/home/kara/ratelimit/limiter.go`:

```go
package ratelimit

import (
	"container/list"
	"sync"
	"time"
)

const (
	defaultShards   = 16
	defaultCapacity = 1024
)

type Limiter struct {
	rate       float64
	burst      float64
	now        func() time.Time
	shardCount int
	capacity   int
	shards     []*shard
}

type Option func(*Limiter)

func WithClock(now func() time.Time) Option { return func(l *Limiter) { l.now = now } }
func WithShards(n int) Option               { return func(l *Limiter) { if n > 0 { l.shardCount = n } } }
func WithCapacity(n int) Option             { return func(l *Limiter) { if n > 0 { l.capacity = n } } }

func New(rate float64, burst int, opts ...Option) *Limiter {
	if rate < 0 || burst < 0 {
		panic("ratelimit: rate and burst must be non-negative")
	}
	l := &Limiter{rate: rate, burst: float64(burst), now: time.Now,
		shardCount: defaultShards, capacity: defaultCapacity}
	for _, o := range opts {
		o(l)
	}
	l.shards = make([]*shard, l.shardCount)
	perShard := (l.capacity + l.shardCount - 1) / l.shardCount // ceil
	for i := range l.shards {
		l.shards[i] = &shard{rate: l.rate, burst: l.burst,
			keys: make(map[string]*bucket), lru: list.New(), capacity: perShard}
	}
	return l
}

type shard struct {
	mu       sync.Mutex
	rate     float64
	burst    float64
	keys     map[string]*bucket
	lru      *list.List // front = most recently used
	capacity int
}

type bucket struct {
	tokens float64
	last   time.Time
	elem   *list.Element
}

// refill applies refill due between b.last and now. Negative elapsed (clock
// moved backwards) is clamped to zero: no tokens for time that did not pass.
func (b *bucket) refill(now time.Time, rate, burst float64) float64 {
	if elapsed := now.Sub(b.last); elapsed > 0 {
		b.tokens += rate * elapsed.Seconds()
		if b.tokens > burst {
			b.tokens = burst // hard cap: full bucket stays exactly full, no drift
		}
		b.last = now
	}
	return b.tokens
}

func (l *Limiter) Allow(key string) bool { return l.AllowN(key, 1) }

func (l *Limiter) AllowN(key string, n int) bool {
	if n <= 0 {
		return true
	}
	s := l.shardFor(key)
	s.mu.Lock()
	defer s.mu.Unlock()
	b := s.touch(key, l.now())
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

func (l *Limiter) Tokens(key string) float64 {
	s := l.shardFor(key)
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.touch(key, l.now()).tokens
}

func (l *Limiter) Reset(key string) {
	s := l.shardFor(key)
	s.mu.Lock()
	defer s.mu.Unlock()
	if b, ok := s.keys[key]; ok {
		s.lru.Remove(b.elem)
		delete(s.keys, key)
	}
}

func (l *Limiter) Size() int {
	total := 0
	for _, s := range l.shards {
		s.mu.Lock()
		total += len(s.keys)
		s.mu.Unlock()
	}
	return total
}

// shardFor maps a key to a shard via FNV-1a (allocation-free).
func (l *Limiter) shardFor(key string) *shard {
	const (offset64 = 14695981039346656037; prime64 = 1099511628211)
	var h uint64 = offset64
	for i := 0; i < len(key); i++ {
		h ^= uint64(key[i])
		h *= prime64
	}
	return l.shards[h%uint64(len(l.shards))]
}

// touch returns the bucket for key, creating it full if absent, applying any
// refill, and refreshing LRU position. Callers must hold s.mu.
func (s *shard) touch(key string, now time.Time) *bucket {
	if b, ok := s.keys[key]; ok {
		b.refill(now, s.rate, s.burst)
		s.lru.MoveToFront(b.elem)
		return b
	}
	b := &bucket{tokens: s.burst, last: now}
	b.elem = s.lru.PushFront(key)
	s.keys[key] = b
	if s.lru.Len() > s.capacity { // bound memory: evict least recently used
		if back := s.lru.Back(); back != nil {
			evicted := back.Value.(string)
			s.lru.Remove(back)
			delete(s.keys, evicted)
		}
	}
	return b
}
